      advanceMinutes: advanceMinutes,
      advanceAlsoExact: advanceAlsoExact,
      advanceNotified: false,
      repeat: repeatVal,
      color: '#3b82f6',
      completed: false,
      notified: false,
      createdAt: new Date().toISOString(),
      updatedAt: new Date().toISOString()
    };

    if (!Array.isArray(this.data.reminders)) {
      this.data.reminders = [];
